from collections import deque

class RelativeDistance:
    def __init__(self, family_tree):
        # store the provided family tree
        # family_tree: dict where keys are parents and values are lists of that parent's children
        self.family_tree = family_tree

        # build set of all individuals present either as a parent (key) or as a child (in values)
        people = set(family_tree.keys())
        for children in family_tree.values():
            people.update(children)
        self._people = people

        # build adjacency (undirected) between parents and children
        adj = {person: set() for person in self._people}
        for parent, children in family_tree.items():
            for child in children:
                # connect parent <-> child
                adj[parent].add(child)
                adj[child].add(parent)
        self._adj = adj

    def degree_of_separation(self, person_a, person_b):
        # validate presence in the family tree (appear as key or as a child)
        if person_a not in self._people:
            raise ValueError("Person A not in family tree.")
        if person_b not in self._people:
            raise ValueError("Person B not in family tree.")

        # same person => zero separation
        if person_a == person_b:
            return 0

        # BFS for shortest path in undirected graph
        queue = deque([person_a])
        visited = {person_a}
        distance = {person_a: 0}

        while queue:
            current = queue.popleft()
            curr_dist = distance[current]
            for neighbor in self._adj.get(current, ()):
                if neighbor not in visited:
                    visited.add(neighbor)
                    distance[neighbor] = curr_dist + 1
                    if neighbor == person_b:
                        return distance[neighbor]
                    queue.append(neighbor)

        # no connection found
        raise ValueError("No connection between person A and person B.")
